mapper.insert:
SELECT SEQ_COMMUNITY_NO.NEXTVAL FROM DUAL
INSERT INTO COMMUNITY_TBL ( COMMUNITY_NO, COMMUNITY_TITLE, COMMUNITY_CONTENT, USER_NO, CREATED_AT, UPDATED_AT, VIEW_COUNT, COMMUNITY_TYPE, SUCCESS_TYPE, GOAL_DATE, DELETE_YN ) VALUES ( #{communityNo}, #{communityTitle}, #{communityContent}, #{userNo}, DEFAULT, NULL, 0, #{communityType}, null, null, DEFAULT
)

INSERT INTO COMMUNITY_IMG_TBL ( IMG_NO, IMG_PATH, IMG_RENAME, IMG_ORIGINAL_NAME, IMG_MAIN, COMMUNITY_NO ) SELECT SEQ_IMG_NO.NEXTVAL, A.* FROM (
SELECT #{img.imgPath} as IMG_PATH, #{img.imgRename} as IMG_RENAME, #{img.imgOriginalName} as IMG_ORIGINAL_NAME, 'N' as IMG_MAIN , #{img.communityNo} as COMMUNITY_NO FROM DUAL
) A

mapper.select:
SELECT * FROM (
	SELECT * FROM NOTICE_TBL WHERE NOTICE_CATEGORY = '공지' ORDER BY CREATED_AT DESC
) WHERE ROWNUM  <=  2

SELECT COUNT(*) 
  FROM COMMUNITY_BOARD_LIKE
 WHERE COMMUNITY_NO = #{communityNo}
   AND USER_NO = #{userNo}

mapper.delete:
DELETE FROM COMMUNITY_BOARD_LIKE
 WHERE COMMUNITY_NO = #{communityNo}
   AND USER_NO = #{userNo}

mapper.select:
SELECT COUNT(*) 
  FROM COMMUNITY_BOARD_LIKE
 WHERE COMMUNITY_NO = #{communityNo}

SELECT C.COMMUNITY_NO, C.COMMUNITY_TITLE, C.COMMUNITY_TYPE, C.COMMUNITY_CONTENT, C.CREATED_AT, C.UPDATED_AT, C.VIEW_COUNT, C.DELETE_YN, C.SUCCESS_TYPE, C.GOAL_DATE, U.USER_NO, U.USER_ID AS userId, U.USER_NICKNAME AS userNickName,
(SELECT IMG_PATH || '/' || IMG_RENAME FROM USER_PROFILE_IMG_TBL WHERE USER_NO = C.USER_NO AND IMG_MAIN = 'Y' AND ROWNUM = 1) AS USER_PROFILE_IMG, (SELECT COUNT(*) FROM COMMUNITY_BOARD_LIKE BL WHERE BL.COMMUNITY_NO = C.COMMUNITY_NO) AS likeCount FROM COMMUNITY_TBL C LEFT JOIN USER_TBL U ON C.USER_NO = U.USER_NO
C.COMMUNITY_TYPE = 'success' AND NVL(C.DELETE_YN,'N') = #{deleteYn}
AND C.SUCCESS_TYPE = #{successType}
AND C.COMMUNITY_TITLE LIKE '%'||#{keyword}||'%'
ORDER BY C.COMMUNITY_NO DESC

SELECT IMG_NO, IMG_PATH, IMG_RENAME, IMG_ORIGINAL_NAME, IMG_MAIN, COMMUNITY_NO
FROM COMMUNITY_IMG_TBL
WHERE IMG_NO = #{imgNo}

mapper.update:
UPDATE COMMUNITY_TBL
SET DELETE_YN = #{deleteYn}
WHERE COMMUNITY_NO = #{communityNo}

UPDATE COMMUNITY_TBL SET COMMUNITY_TITLE = #{cDTO.communityTitle}, COMMUNITY_TYPE = #{cDTO.communityType}, 
COMMUNITY_CONTENT = #{cDTO.communityContent} 
WHERE USER_NO = #{userNo} AND COMMUNITY_NO = #{cDTO.communityNo}
